open(libp,'w').write('''def find_frame(grid):
    """The color that forms two or more full rows and two or more full columns (the grid's frame), else None."""
    h, w = len(grid), len(grid[0])
    for c in {v for row in grid for v in row} - {0}:
        rows = [i for i in range(h) if all(grid[i][j] == c for j in range(w))]
        cols = [j for j in range(w) if all(grid[i][j] == c for i in range(h))]
        if len(rows) >= 2 and len(cols) >= 2:
            return c
    return None

def frame_starts(grid, frame=None):
    """Top-left coordinates (row, col) of every frame-delimited block cell, as (row_starts, col_starts)."""
    frame = frame if frame is not None else find_frame(grid)
    h, w = len(grid), len(grid[0])
    frows = [i for i in range(h) if all(grid[i][j] == frame for j in range(w))]
    fcols = [j for j in range(w) if all(grid[i][j] == frame for i in range(h))]
    return [0] + [r + 1 for r in frows], [0] + [c + 1 for c in fcols]

def cell_of(grid, i, j, frame=None):
    """The top-left coordinate of the frame-delimited block cell containing (i, j)."""
    rstarts, cstarts = frame_starts(grid, frame)
    return max(s for s in rstarts if s <= i), max(s for s in cstarts if s <= j)

def color_cells(grid, frame=None):
    """Map of each non-frame, non-background color to the top-left of the block cell holding it."""
    frame = frame if frame is not None else find_frame(grid)
    h, w = len(grid), len(grid[0])
    out = {}
    for i in range(h):
        for j in range(w):
            c = grid[i][j]
            if c in (0, frame):
                continue
            cells = [(a, b) for a in range(h) for b in range(w) if grid[a][b] == c]
            if (i, j) == (min(a for a, b in cells), min(b for a, b in cells)):
                out[c] = cell_of(grid, i, j, frame)
    return out

def bbox_pattern(grid, color):
    """Binary pattern of the color's bounding box: 1 where the box holds that color, 0 elsewhere."""
    cells = [(i, j) for i, row in enumerate(grid) for j, v in enumerate(row) if v == color]
    r0, r1 = min(i for i, j in cells), max(i for i, j in cells) + 1
    c0, c1 = min(j for i, j in cells), max(j for i, j in cells) + 1
    return [[1 if grid[i][j] == color else 0 for j in range(c0, c1)] for i in range(r0, r1)]

def stamp(grid, pat, top, left, color, frame=None):
    """Paint pattern pat (1s become color, 0s become background) at (top, left), keeping frame lines."""
    h, w = len(grid), len(grid[0])
    frame = frame if frame is not None else find_frame(grid)
    out = [row[:] for row in grid]
    for a in range(len(pat)):
        for b in range(len(pat[0])):
            if frame is None or out[top + a][left + b] != frame:
                out[top + a][left + b] = color * pat[a][b]
    return out

def clear_grid(grid, frame=None):
    """The grid with everything except its frame lines set to background 0."""
    frame = frame if frame is not None else find_frame(grid)
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    if frame is not None:
        for i in range(h):
            if all(grid[i][j] == frame for j in range(w)):
                out[i] = [frame] * w
        for j in range(w):
            if all(grid[i][j] == frame for i in range(h)):
                for i in range(h):
                    out[i][j] = frame
    return out
